const API_HEADERS={Authorization:`Bearer ${localStorage.getItem("access_token")||sessionStorage.getItem("access_token")}`,"Content-Type":"application/json"},systemHistory={cpu:[],memory:[],labels:[]},MAX_DATA_POINTS=30;let systemChart=null;const MONITORING_POLL_INTERVAL_MS=3e3;let healthFetchInFlight=!1,refreshTimer=null;function initCharts(){const ctx=document.getElementById("systemChart");if(!ctx){console.warn("Canvas #systemChart not found!");return}const commonOptions={responsive:!0,maintainAspectRatio:!1,plugins:{legend:{labels:{color:"#e0e0e0"}}},scales:{y:{beginAtZero:!0,max:100,ticks:{color:"#888"},grid:{color:"rgba(255, 255, 255, 0.1)"}},x:{ticks:{color:"#888",maxRotation:0,autoSkip:!0,maxTicksLimit:6},grid:{display:!1}}},animation:{duration:0}};systemChart=new Chart(ctx,{type:"line",data:{labels:systemHistory.labels,datasets:[{label:"CPU %",data:systemHistory.cpu,borderColor:"#0d6efd",backgroundColor:"rgba(13, 110, 253, 0.1)",borderWidth:2,fill:!0,tension:.4,pointRadius:0},{label:"RAM %",data:systemHistory.memory,borderColor:"#198754",backgroundColor:"rgba(25, 135, 84, 0.1)",borderWidth:2,fill:!0,tension:.4,pointRadius:0}]},options:commonOptions})}async function fetchHealthData(){if(!healthFetchInFlight){healthFetchInFlight=!0;try{const response=await fetch("/api/health/detailed",{headers:API_HEADERS});if(!response.ok){if(response.status===401||response.status===403){typeof NavigationManager!="undefined"?NavigationManager.forceLogout():(localStorage.removeItem("access_token"),sessionStorage.removeItem("access_token"),window.location.href="/");return}console.error("Health API Error:",response.status);return}const data=await response.json();updateUI(data),updateCharts(data)}catch(error){console.error("Error fetching health data:",error)}finally{healthFetchInFlight=!1}}}function updateUI(data){if(!(data!=null&&data.system))return;const setText=(id,val)=>{const el=document.getElementById(id);el&&(el.textContent=val)};setText("cpu-percent",`${data.system.cpu_percent.toFixed(1)}%`),setText("memory-percent",`${data.system.memory_percent.toFixed(1)}%`),setText("disk-percent",`${data.system.disk_percent.toFixed(1)}%`),data.application&&setText("avg-response-time",`${data.application.avg_response_time_ms.toFixed(1)}ms`)}function updateCharts(data){if(!systemChart||!data.system)return;const now=new Date().toLocaleTimeString("en-US",{hour12:!1,hour:"numeric",minute:"numeric",second:"numeric"});systemHistory.cpu.push(data.system.cpu_percent),systemHistory.memory.push(data.system.memory_percent),systemHistory.labels.push(now),systemHistory.cpu.length>MAX_DATA_POINTS&&(systemHistory.cpu.shift(),systemHistory.memory.shift(),systemHistory.labels.shift()),systemChart.data.labels=systemHistory.labels,systemChart.data.datasets[0].data=systemHistory.cpu,systemChart.data.datasets[1].data=systemHistory.memory,systemChart.update("none")}function startMonitoringPolling(){stopMonitoringPolling(),fetchHealthData(),refreshTimer=setInterval(()=>{document.hidden||fetchHealthData()},MONITORING_POLL_INTERVAL_MS)}function stopMonitoringPolling(){refreshTimer&&(clearInterval(refreshTimer),refreshTimer=null)}document.addEventListener("DOMContentLoaded",()=>{if(!(localStorage.getItem("access_token")||sessionStorage.getItem("access_token"))){typeof NavigationManager!="undefined"?NavigationManager.forceLogout():(localStorage.removeItem("access_token"),sessionStorage.removeItem("access_token"),window.location.href="/");return}initCharts(),startMonitoringPolling(),document.addEventListener("visibilitychange",()=>{if(document.hidden){stopMonitoringPolling();return}startMonitoringPolling()})}),window.addEventListener("beforeunload",()=>{stopMonitoringPolling()});
